sn_ui_builder_props_config.scripted_config_policy:
// eslint-disable-next-line no-unused-vars
            function configureProps(obj) {
                const { trigger, api, properties } = obj;

                const toggleVisibility = (property, value) => {
                    api.updateVisibility(property, value);
                };

                const updatePlaybookPropertiesVisibility = () => {
                    const playbookProperties = [
                        { property: 'playbookExperience', value: !properties.hidePlaybookProcessTab },
                        { property: 'playbookStageOrientation', value: !properties.hidePlaybookProcessTab && !properties.hidePlaybookStages },
                        { property: 'visibleHorizontalPlaybookStages', value: !properties.hidePlaybookProcessTab && !properties.hidePlaybookStages && properties.playbookStageOrientation === 'horizontal' },
                        { property: 'playbookActivityViewMode', value: !properties.hidePlaybookProcessTab },
						{ property: 'hidePlaybookStages', value: !properties.hidePlaybookProcessTab }
                    ];
                    playbookProperties.forEach(({ property, value }) => {
                        toggleVisibility(property, value);
                    });
                };

                const updateTriggerSpecificVisibility = () => {
                    switch (trigger) {
                        case 'hideActions':
                            toggleVisibility('actionConfigurationId', !properties.hideActions);
                            break;
                        case 'hideAllRelatedLists':
                            toggleVisibility('tableViewForRelatedList', !properties.hideAllRelatedLists);
                            break;
                        case 'hideActivity':
                            toggleVisibility('enableRichText', !properties.hideActivity);
                            break;
                        default:
                            break;
                    }
                };

                if(trigger)
                    updateTriggerSpecificVisibility();
                updatePlaybookPropertiesVisibility();
        }
